using Microsoft::WRL::ComPtr;namespace fs=std::filesystem;
void check(HRESULT h,const char*what){if(FAILED(h)){printf("FAIL: %s 0x%08lx\n",what,h);exit(1);}}
std::vector<char> bytes(fs::path p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
ComPtr<ID3DBlob> compile(fs::path p,const char*entry,const char*target,const std::string&fn,bool mutate=false){ComPtr<ID3DBlob>b,e;D3D_SHADER_MACRO defs[]={{"GRAPH_FUNCTION",fn.c_str()},{"MUTATED_GRAPH",mutate?"1":"0"},{nullptr,nullptr}};auto h=D3DCompileFromFile(p.c_str(),defs,D3D_COMPILE_STANDARD_FILE_INCLUDE,entry,target,D3DCOMPILE_OPTIMIZATION_LEVEL3,0,&b,&e);if(FAILED(h)&&e)printf("%s\n",(char*)e->GetBufferPointer());check(h,"compile translated graph");return b;}
int main(int argc,char**argv){fs::path root=argv[1];int only=argc>2?atoi(argv[2]):0;bool mutate=argc>3;ComPtr<ID3D11Device>d;ComPtr<ID3D11DeviceContext>c;D3D_FEATURE_LEVEL fl;check(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,0,nullptr,0,D3D11_SDK_VERSION,&d,&fl,&c),"device");
 const UINT W=32,H=32;ComPtr<ID3D11Texture2D> out[3],staging[3];ComPtr<ID3D11RenderTargetView>rt[3];for(int j=0;j<3;++j){D3D11_TEXTURE2D_DESC t{};t.Width=W;t.Height=H;t.MipLevels=t.ArraySize=1;t.Format=DXGI_FORMAT_R32G32B32A32_FLOAT;t.SampleDesc.Count=1;t.BindFlags=D3D11_BIND_RENDER_TARGET;check(d->CreateTexture2D(&t,nullptr,&out[j]),"target");check(d->CreateRenderTargetView(out[j].Get(),nullptr,&rt[j]),"rtv");t.BindFlags=0;t.Usage=D3D11_USAGE_STAGING;t.CPUAccessFlags=D3D11_CPU_ACCESS_READ;check(d->CreateTexture2D(&t,nullptr,&staging[j]),"staging");}
 ComPtr<ID3D11Texture2D>textures[9];ComPtr<ID3D11ShaderResourceView>views[9];for(int i=0;i<9;++i){D3D11_TEXTURE2D_DESC t{};t.Width=t.Height=64;t.MipLevels=t.ArraySize=1;t.Format=DXGI_FORMAT_R32G32B32A32_FLOAT;t.SampleDesc.Count=1;t.BindFlags=D3D11_BIND_SHADER_RESOURCE;std::vector<float>pixels(64*64*4);for(int p=0;p<64*64;++p)for(int k=0;k<4;++k)pixels[4*p+k]=i==8?1.7f:std::min(0.9f,0.1f+float(k)*0.12f+float(i)*0.03f+float(p%64)*0.002f+float(p/64)*0.001f);D3D11_SUBRESOURCE_DATA init{pixels.data(),64*16,0};check(d->CreateTexture2D(&t,&init,&textures[i]),"map");check(d->CreateShaderResourceView(textures[i].Get(),nullptr,&views[i]),"srv");}
 D3D11_SAMPLER_DESC sm{};sm.Filter=D3D11_FILTER_MIN_MAG_MIP_POINT;sm.AddressU=sm.AddressV=sm.AddressW=D3D11_TEXTURE_ADDRESS_WRAP;sm.MaxAnisotropy=16;sm.MaxLOD=D3D11_FLOAT32_MAX;ComPtr<ID3D11SamplerState>sampler;check(d->CreateSamplerState(&sm,&sampler),"sampler");ID3D11SamplerState*samplers[16];std::fill_n(samplers,16,sampler.Get());c->PSSetSamplers(0,16,samplers);ID3D11RenderTargetView*rts[3]={rt[0].Get(),rt[1].Get(),rt[2].Get()};c->OMSetRenderTargets(3,rts,nullptr);D3D11_VIEWPORT vp{0,0,float(W),float(H),0,1};c->RSSetViewports(1,&vp);c->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
 D3D11_RASTERIZER_DESC rs{};rs.FillMode=D3D11_FILL_SOLID;rs.CullMode=D3D11_CULL_NONE;rs.DepthClipEnable=TRUE;ComPtr<ID3D11RasterizerState>raster;check(d->CreateRasterizerState(&rs,&raster),"raster");c->RSSetState(raster.Get());
 auto draw=[&](ID3D11PixelShader*ps){float zero[4]{};for(auto&r:rt)c->ClearRenderTargetView(r.Get(),zero);c->PSSetShader(ps,nullptr,0);c->Draw(3,0);std::vector<float>v(W*H*12);for(int j=0;j<3;++j){c->CopyResource(staging[j].Get(),out[j].Get());D3D11_MAPPED_SUBRESOURCE m{};check(c->Map(staging[j].Get(),0,D3D11_MAP_READ,0,&m),"readback");for(UINT y=0;y<H;++y)memcpy(v.data()+j*W*H*4+y*W*4,(char*)m.pData+y*m.RowPitch,W*16);c->Unmap(staging[j].Get(),0);}return v;};
 std::ifstream jobs(root/"jobs.txt");std::string job;int checks=0;while(std::getline(jobs,job)){if(const char* selected=getenv("DECAL_REFERENCE_JOB")) if(job!=selected)continue;if(const char* selected=getenv("DECAL_REFERENCE_JOB")) if(job!=selected)continue;auto data=bytes(root/(job+".bin"));size_t pos=0;auto read=[&](){UINT x;memcpy(&x,data.data()+pos,4);pos+=4;return x;};UINT kind=read(),emission=read(),nb=read(),nt=read();if(only&&kind!=only)continue;std::string function="decal_graph_"+std::to_string(kind)+(emission?"_emission":"_paint");auto shader=compile(root/"reference.hlsl","main","ps_5_0",function,mutate);ComPtr<ID3D11PixelShader>actual,expected;check(d->CreatePixelShader(shader->GetBufferPointer(),shader->GetBufferSize(),nullptr,&actual),"lifted PS");auto original=bytes(root/(job+".dxbc"));check(d->CreatePixelShader(original.data(),original.size(),nullptr,&expected),"original PS");auto vs=compile(root/"reference.hlsl",kind==7?"bfxvs":"vs","vs_5_0",function);ComPtr<ID3D11VertexShader>vertex;check(d->CreateVertexShader(vs->GetBufferPointer(),vs->GetBufferSize(),nullptr,&vertex),"VS");c->VSSetShader(vertex.Get(),nullptr,0);
 D3D11_BUFFER_DESC bd{};bd.ByteWidth=656;bd.StructureByteStride=656;bd.BindFlags=D3D11_BIND_SHADER_RESOURCE;bd.MiscFlags=D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;D3D11_SUBRESOURCE_DATA initial{data.data()+pos,0,0};pos+=656;ComPtr<ID3D11Buffer>record;ComPtr<ID3D11ShaderResourceView>recordView;check(d->CreateBuffer(&bd,&initial,&record),"record");check(d->CreateShaderResourceView(record.Get(),nullptr,&recordView),"record view");
 ComPtr<ID3D11Buffer>constants[16];ID3D11Buffer*cb[16]{};for(UINT b=0;b<nb;++b){UINT slot=read(),size=read();D3D11_BUFFER_DESC desc{};desc.ByteWidth=size;desc.BindFlags=D3D11_BIND_CONSTANT_BUFFER;D3D11_SUBRESOURCE_DATA init{data.data()+pos,0,0};pos+=size;check(d->CreateBuffer(&desc,&init,&constants[slot]),"constant buffer");cb[slot]=constants[slot].Get();}c->PSSetConstantBuffers(0,14,cb);
 ID3D11ShaderResourceView*source[16]{};for(UINT i=0;i<nt;++i){UINT slot=read();int index=int(read());source[slot]=views[index==-2?8:index].Get();}c->PSSetShaderResources(0,16,source);auto ref=draw(expected.Get());ID3D11ShaderResourceView*lifted[16]{};for(int i=0;i<8;++i)lifted[i]=views[i].Get();lifted[10]=recordView.Get();c->PSSetShaderResources(0,16,lifted);auto result=draw(actual.Get());
 double error=0,largest=0,scaled=0,energy=0;size_t finite=0;for(size_t i=0;i<ref.size();++i){if(emission&&i>=W*H*4)continue;if(std::isfinite(ref[i])&&std::isfinite(result[i])){double v=std::abs(double(ref[i])-result[i]);error+=v;largest=std::max(largest,v);scaled=std::max(scaled,v/std::max(1.0,std::abs(double(ref[i]))));energy+=std::abs(ref[i]);++finite;}else if(std::isfinite(ref[i])!=std::isfinite(result[i])){largest=scaled=INFINITY;}}printf("%s: max %.8g mean %.8g, reference magnitude %.8g, %zu finite channels\n",job.c_str(),largest,error/std::max(size_t(1),finite),energy/std::max(size_t(1),finite),finite);fflush(stdout);printf("      maximum error / max(1, reference) %.8g\n",scaled);if(!(scaled<0.0003)){printf("FAIL: translated %s matches the original compiled pixel program\n",job.c_str());return 1;}++checks;}
 printf("all %d original-program comparisons passed\n",checks);return 0;}
